+import java.util.Arrays;
+import java.util.HashSet;
+import java.util.Set;
+
+public class UrlService {
+
+    private static final Set<String> ALLOWED_SCHEMES = new HashSet<>(Arrays.asList("http", "https"));
+    private static final int CONNECT_TIMEOUT_MS = 5000;
+    private static final int SOCKET_TIMEOUT_MS = 10000;
+
+    public String fetchUrlContent(String userUrl) throws Exception {
+        if (userUrl == null || userUrl.trim().isEmpty()) {
+            throw new IllegalArgumentException("URL must not be null or empty");
+        }
+
+        URI uri = validateAndParseUrl(userUrl);
+        validateScheme(uri);
+        validateHost(uri);
+
+        RequestConfig requestConfig = RequestConfig.custom()
+                .setConnectTimeout(CONNECT_TIMEOUT_MS)
+                .setSocketTimeout(SOCKET_TIMEOUT_MS)
+                .setRedirectsEnabled(false)
+                .build();
+
+        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
+            HttpGet httpGet = new HttpGet(uri);
+            httpGet.setConfig(requestConfig);
+
+            HttpResponse response = httpClient.execute(httpGet);
+            int statusCode = response.getStatusLine().getStatusCode();
+
+            if (statusCode >= 200 && statusCode < 300) {
+                return EntityUtils.toString(response.getEntity());
+            } else {
+                EntityUtils.consume(response.getEntity());
+                throw new RuntimeException("HTTP request failed with status code: " + statusCode);
