+    private URI validateAndParseUrl(String userUrl) {
+        try {
+            return new URI(userUrl);
+        } catch (Exception e) {
+            throw new IllegalArgumentException("Invalid URL: " + userUrl, e);
+        }
+    }
+
+    private void validateScheme(URI uri) {
+        String scheme = uri.getScheme();
+        if (scheme == null || !ALLOWED_SCHEMES.contains(scheme.toLowerCase())) {
+            throw new IllegalArgumentException("Only HTTP and HTTPS protocols are allowed");
+        }
+    }
+
+    private void validateHost(URI uri) {
+        String host = uri.getHost();
+        if (host == null || host.isEmpty()) {
+            throw new IllegalArgumentException("URL must have a valid host");
+        }
+
+        try {
+            InetAddress address = InetAddress.getByName(host);
+            if (isPrivateOrReservedAddress(address)) {
+                throw new IllegalArgumentException("Requests to private or reserved IP addresses are not allowed");
+            }
+        } catch (IllegalArgumentException e) {
+            throw e;
+        } catch (Exception e) {
+            throw new RuntimeException("Failed to resolve host: " + host, e);
+        }
+    }
+
+    private boolean isPrivateOrReservedAddress(InetAddress address) {
+        return address.isLoopbackAddress()
+                || address.isSiteLocalAddress()
+                || address.isLinkLocalAddress()
+                || address.isAnyLocalAddress()
+                || address.isMulticastAddress();
+    }
